css:
.loader { position: relative; display: inline-block; width: var(--loader-size); height: var(--loader-size); }
.loader .pin { position: absolute; left: 50%; top: 10%; width: calc(var(--loader-size) * .44); height: calc(var(--loader-size) * .44); margin-left: calc(var(--loader-size) * -.22); border-radius: 50% 50% 50% 0; background: var(--loader-color); animation: twDrop calc(var(--loader-speed) * 1.8) cubic-bezier(.5, 0, .5, 1) infinite; }
.loader .pin::after { content: ''; position: absolute; left: 28%; top: 28%; width: 44%; height: 44%; border-radius: 9999px; background: color-mix(in srgb, #ffffff 78%, var(--loader-color)); }
.loader .shadow { position: absolute; left: 50%; bottom: 10%; width: calc(var(--loader-size) * .34); height: calc(var(--loader-size) * .09); margin-left: calc(var(--loader-size) * -.17); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color) 38%, transparent); animation: twShadow calc(var(--loader-speed) * 1.8) cubic-bezier(.5, 0, .5, 1) infinite; }
@keyframes twDrop { 0%, 100% { transform: translateY(-16%) rotate(-45deg); } 50% { transform: translateY(20%) rotate(-45deg); } }
@keyframes twShadow { 0%, 100% { transform: scale(.7); opacity: .3; } 50% { transform: scale(1); opacity: .75; } }
